(function(){function d(){let r=document.getElementById("servings-display");if(!r)return;let s=parseInt(r.dataset.base??"1",10),a=s;function l(t){if(Number.isInteger(t))return t;let n=Math.round(t*10)/10;return Number.isInteger(n),n}function c(t){a=Math.max(1,a+t),r.textContent=String(a);let n=a/s;document.querySelectorAll(".scalable-value").forEach(e=>{let o=parseFloat(e.dataset.base??"0");e.textContent=String(l(o*n))}),document.querySelectorAll(".scalable-range").forEach(e=>{let o=parseFloat(e.dataset.baseLow??"0"),i=parseFloat(e.dataset.baseHigh??"0");e.textContent=`${l(o*n)}-${l(i*n)}`})}document.querySelectorAll(".servings-btn[data-delta]").forEach(t=>{let n=parseInt(t.dataset.delta??"0",10),e=()=>c(n);t.addEventListener("click",e),window.addCleanup(()=>t.removeEventListener("click",e))})}document.addEventListener("nav",d)})();
